    totalWords = 0
    insideCounter = 0
    outsideWord = False
    insideWord = False
    insideParentheses = False

    position = 0

    while position < totalLength:
        ch = inputStr[position]
        if ch == '(':
            insideParentheses = True
            insideCounter += 1
            if maxWordLength < currentLength:
                maxWordLength = currentLength
            currentLength = 0
            outsideWord = False
        elif ch == ')':
            insideParentheses = False
            insideCounter = 0
            if insideCounter > 0:
                totalWords += 1
        else:
            if insideCounter > 0:
                insideParentheses = True

        if position == totalLength:
            break

        if ch != ')' and ch != '(':
            if not insideParentheses:
                if ch == '_':
                    if maxWordLength < currentLength:
                        maxWordLength = currentLength
                    currentLength = 0
                    outsideWord = False
                else:
                    outsideWord = True

                if outsideWord:
                    currentLength += 1
            else:
                outsideWord = False
                if ch == '_':
                    if insideCounter > 0:
                        totalWords += 1
                    insideCounter = 0
                    insideWord = False
